package net.civeira.phylax.feature.observe.observedprobe.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class LastLatencyMsVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property last latency ms of observed probe ")
  void test_last_latency_ms_v_o_builder() {
    Assertions.assertFalse(LastLatencyMsVO.nullValue().getLastLatencyMs().isPresent(),
        "A empty vo should have a null value");
    Assertions.assertFalse(LastLatencyMsVO.tryFrom(null).getLastLatencyMs().isPresent(),
        "With a null value, no present result");
    Assertions.assertEquals(1, LastLatencyMsVO.from(1).getLastLatencyMs().orElse(null));
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class,
        () -> LastLatencyMsVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + 1 + "]", LastLatencyMsVO.from(1).toString());
  }
}
